const item = $input.first().json;
const currentApps = item.apps || item.authorizedApps || [];
const baseline = item.baseline || item.knownApps || [];

const baselineByAppId = {};
for (const b of baseline) baselineByAppId[b.appId] = b;

const flagged = [];
for (const app of currentApps) {
  const known = baselineByAppId[app.appId];
  const scopes = (app.scopes || []).slice().sort();

  if (!known) {
    flagged.push({ ...app, scopes, flagReason: 'new_app' });
    continue;
  }

  const knownScopes = (known.scopes || []).slice().sort();
  const scopesChanged = JSON.stringify(scopes) !== JSON.stringify(knownScopes);
  if (scopesChanged) {
    flagged.push({ ...app, scopes, previousScopes: knownScopes, flagReason: 'scope_change' });
  }
}

return [{
  json: {
    scanTimestamp: new Date().toISOString(),
    totalAppsScanned: currentApps.length,
    flaggedApps: flagged,
    hasFlagged: flagged.length > 0
  }
}];

const upstream = $('IF - New or Changed Grants Found?').first().json;
const reputationResp = $input.first().json;
const reputationByAppId = {};
for (const r of (reputationResp.results || reputationResp.reputations || [])) {
  reputationByAppId[r.appId] = r;
}

const enriched = upstream.flaggedApps.map(a => {
  const rep = reputationByAppId[a.appId] || {};
  return {
    ...a,
    publisherReputationScore: rep.reputationScore ?? null,
    publisherVerified: rep.verified ?? false,
    knownMalicious: rep.knownMalicious ?? false
  };
});

return [{ json: { scanTimestamp: upstream.scanTimestamp, flaggedApps: enriched } }];

parameters.text:
=You are an identity security reviewer assessing newly authorized or changed third-party OAuth applications.

Flagged applications this cycle:
{{ JSON.stringify($json.flaggedApps, null, 2) }}

For each app, assess risk based on: how sensitive/excessive the requested scopes are relative to what the app claims to do, publisher verification and reputation score, whether it's flagged as known malicious, and whether this is a brand-new app vs a scope change on a previously-trusted app (scope escalation on a trusted app can be just as risky as a brand-new unverified app).

Assign each app a risk tier of High, Medium, or Low.

Return a JSON object with EXACTLY this shape:
{
  "assessments": [
    {
      "appId": "string, matching input exactly",
      "riskTier": "High" or "Medium" or "Low",
      "reasoning": "one short sentence"
    }
  ]
}

Return ONLY the JSON. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
const upstream = $('JS - Attach Reputation to Flagged Apps').first().json;

let assessments = [];
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  assessments = parsed.assessments || [];
} catch (e) {
  // Fallback: if parsing fails, treat every flagged app as Medium risk (safe default: human review, no auto-revoke)
  assessments = (upstream.flaggedApps || []).map(a => ({
    appId: a.appId,
    riskTier: 'Medium',
    reasoning: 'AI risk scoring unavailable this cycle; routed to manual review as a safety default.'
  }));
}

const assessmentByAppId = {};
for (const a of assessments) assessmentByAppId[a.appId] = a;

const scoredApps = (upstream.flaggedApps || []).map(app => {
  const a = assessmentByAppId[app.appId];
  return {
    ...app,
    riskTier: a ? a.riskTier : 'Medium',
    riskReasoning: a ? a.reasoning : 'No assessment returned; defaulted to manual review.'
  };
});

return scoredApps.map(app => ({ json: app }));
